import{_ as l,o as a,c as e,a as i}from"./app.acd7d7d6.js";const b=JSON.parse('{"title":"陈民","description":"","frontmatter":{},"headers":[],"relativePath":"about/about-my-resume0.md","filePath":"about/about-my-resume0.md","lastUpdated":1772097588000}'),r={name:"about/about-my-resume0.md"};function o(n,t,s,h,u,d){return a(),e("div",null,t[0]||(t[0]=[i('<h1 id="陈民" tabindex="-1">陈民 <a class="header-anchor" href="#陈民" aria-label="Permalink to &quot;陈民&quot;">​</a></h1><h2 id="个人信息" tabindex="-1">个人信息 <a class="header-anchor" href="#个人信息" aria-label="Permalink to &quot;个人信息&quot;">​</a></h2><table><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>姓名</td><td>陈民</td></tr><tr><td>性别</td><td>男</td></tr><tr><td>出生年月</td><td>1993.8</td></tr><tr><td>民族</td><td>汉</td></tr><tr><td>专业</td><td>计算机应用技术</td></tr><tr><td>求职意向</td><td>Web 前端开发（GIS / 数据可视化方向）</td></tr><tr><td>电子邮箱</td><td><a href="mailto:zmx2321@163.com" target="_blank" rel="noreferrer">zmx2321@163.com</a></td></tr><tr><td>联系电话</td><td>18329042835</td></tr></tbody></table><h3 id="技术主页" tabindex="-1">技术主页 <a class="header-anchor" href="#技术主页" aria-label="Permalink to &quot;技术主页&quot;">​</a></h3><ul><li><strong>Github</strong>: <a href="https://github.com/zmx2321" target="_blank" rel="noreferrer">https://github.com/zmx2321</a></li><li><strong>掘金</strong>: <a href="https://juejin.im/user/5d26e83451882554c007b4f0" target="_blank" rel="noreferrer">https://juejin.im/user/5d26e83451882554c007b4f0</a></li><li><strong>技术博客</strong>: <a href="https://zmx2321.github.io/vite-blog/" target="_blank" rel="noreferrer">https://zmx2321.github.io/vite-blog/</a></li><li><strong>项目 Demo</strong>: <a href="https://zmx2321.github.io/vue3-admin-demo" target="_blank" rel="noreferrer">https://zmx2321.github.io/vue3-admin-demo</a></li><li><strong>公众号</strong>: zmx 的前端日志</li></ul><hr><h2 id="核心优势" tabindex="-1">核心优势 <a class="header-anchor" href="#核心优势" aria-label="Permalink to &quot;核心优势&quot;">​</a></h2><ol><li><p><strong>8年政企数字化/智慧城市深耕</strong>，落地10+GIS/数据可视化核心项目，熟练掌握政务大数据开发规范，入职可独立扛岗、统筹开发，高度匹配杭州本地政企技术需求；</p></li><li><p><strong>GIS+前端深度融合</strong>，精通Vue 全生态+Openlayer/Mapbox/高德二维开发，掌握Cesium 三维技术，实现空间与业务数据全链路可视化开发；</p></li><li><p><strong>全流程数据处理能力</strong>，熟练掌握Python 高级爬虫（瑞数反爬/Webpack 逆向/AES/RSA 加解密）以及PostGIS/MySQL 地理数据库，独立完成合规采集清洗-地理化存储可视化完整数据闭环；</p></li><li><p><strong>全栈开发+AI 提效</strong>，掌握Java 若依框架，可完成前端+数据采集+GIS 存储+后端全流程开发，AI 工具融入开发全链路，大幅提升项目交付效率；</p></li><li><p>具备前端组件化/工程化开发思维，擅长需求拆解与技术方案制定，可统筹开发进度，精准适配政企GIS 类项目全链路需求。</p></li></ol><hr><h2 id="专业技能" tabindex="-1">专业技能 <a class="header-anchor" href="#专业技能" aria-label="Permalink to &quot;专业技能&quot;">​</a></h2><h3 id="前端-gis-开发" tabindex="-1">前端 &amp; GIS 开发 <a class="header-anchor" href="#前端-gis-开发" aria-label="Permalink to &quot;前端 &amp; GIS 开发&quot;">​</a></h3><ul><li>熟练掌握 Vue2/Vue3+TS/Vite/ElementPlus 全套技术栈，理解 MVVM 思想，擅长通用组件/业务模块封装，熟练掌握 PC/移动端响应式开发；</li><li>深耕 GIS 地图开发，熟练掌握 Openlayer/Mapbox/高德二维地图，了解 Cesium 三维地图及 GIS 相关技术，能封装地图核心方法并实现个性化业务开发；</li><li>熟练掌握微信小程序原生、UniApp 跨端开发，能完成从构建、开发到发布全流程；熟练掌握 Flex 布局、CSS3动画，可通过 Less/Sass/Stylus 高度还原设计稿；</li><li>熟练使用 Git/SVN 版本控制、Nginx 部署，可在 Windows/Linux 搭建前后端开发环境；熟悉浏览器运行机制，掌握 sessionStorage/indexedDB 本地存储、WebSocket 实时通信，解决大体积数据存储、实时推送等技术难点。</li></ul><h3 id="python-爬虫-数据处理" tabindex="-1">Python 爬虫 &amp; 数据处理 <a class="header-anchor" href="#python-爬虫-数据处理" aria-label="Permalink to &quot;Python 爬虫 &amp; 数据处理&quot;">​</a></h3><ul><li>熟练掌握 Python 基础语法，熟练使用 Python 做数据采集、清洗、处理、入库，可编写脚本实现 CSV/Excel 数据自动化计算、入库及文件生成；</li><li>具备高级爬虫实战能力，可完成补环境、瑞数反爬、Webpack 逆向，熟练掌握 AES/RSA 加解密，能破解请求/响应加密接口获取批量数据；</li><li>熟练使用 Python 爬虫相关库，可将采集数据存入 MySQL、PostgreSQL 数据库（可集成 PostGIS 地理信息扩展），完成 GIS 地理数据、业务数据的专业化存储与可视化前置处理，形成「采集清洗-地理化存储可视化」完整数据闭环；</li><li>了解 Node.js，可使用 Express/Koa 开发简单接口，结合 Nightmare/Puppeteer 实现模拟浏览器请求的爬虫开发。</li></ul><h3 id="后端-ai-工具-其他能力" tabindex="-1">后端 &amp; AI 工具 &amp; 其他能力 <a class="header-anchor" href="#后端-ai-工具-其他能力" aria-label="Permalink to &quot;后端 &amp; AI 工具 &amp; 其他能力&quot;">​</a></h3><ul><li>熟练掌握 Java 基础，熟练使用若依框架完成增删改查接口开发，能独立完成小型模块前后端全栈开发；</li><li>熟练掌握 MySQL、PostgreSQL 数据库基础操作与设计，可在 PostgreSQL 中集成 PostGIS 地理信息扩展，实现 GIS 空间数据的存储、查询与关联分析，适配政企地理信息类项目数据需求；</li><li>熟练使用 Cursor、通义灵码、Trae 等主流 AI 编程工具，精通 AI 辅助代码生成、项目重构、调试优化、需求拆解等实操能力，将 AI 工具深度融入编码、调试、部署全流程，大幅提升开发效率与项目交付速度；</li><li>掌握前端工程化、组件化开发思想，具备需求拆解与落地能力，能将业务需求提炼为技术功能点，制定前端开发方案并统筹开发进度。</li></ul><hr><h2 id="工作经历" tabindex="-1">工作经历 <a class="header-anchor" href="#工作经历" aria-label="Permalink to &quot;工作经历&quot;">​</a></h2><h3 id="中国移动设计院-web-前端开发-2024-04-至今" tabindex="-1">中国移动设计院 | Web 前端开发 | 2024.04 - 至今 <a class="header-anchor" href="#中国移动设计院-web-前端开发-2024-04-至今" aria-label="Permalink to &quot;中国移动设计院 | Web 前端开发 | 2024.04 - 至今&quot;">​</a></h3><p><strong>核心方向</strong>: 政企数字化项目开发 | GIS 地图开发 | Python 高级爬虫 | AI 功能开发 | 若依框架后端开发 | GIS 数据存储</p><ol><li><p><strong>无线网质量评估系统（政企核心项目）多模块开发</strong>：</p><ul><li>独立完成 GIS 模块全开发，基于 Openlayer 封装核心方法实现组件化调用，改造气泡窗支持 Element-UI 渲染，提升模块复用性；</li><li>授权后通过 Python 高级爬虫破解加密接口，采集批量基站 GIS 与业务数据，存入 PostgreSQL+PostGIS 数据库，为基站修复提供多维度数据支撑；</li><li>开发 AI 会话助手，支持语音/文字输入，可识别 SQL 请求并执行，动态生成表格/图表/地图标注；</li><li>独立完成诉中管控模块前后端开发，开发专属接口，实现与微信机器人的定时任务数据实时同步，支撑政企诉中管控高效落地。</li></ul></li><li><p><strong>独立开发 CSV 数据自动化同步项目</strong>：</p><ul><li>编写 Python 脚本实现 5 张基表+4 张固定表自动化计算、3 张结果表批量入库 PostgreSQL，一键完成数据处理、入库及 Excel 文件生成，将月度人工数据同步工作优化为自动化操作，大幅提升政企数据处理效率。</li></ul></li><li><p><strong>独立承接 OMC 服务器管理平台开发</strong>：</p><ul><li>承接 100+台 OMC 服务器管理平台开发，独立完成需求拆解、前端全模块开发及开发进度统筹；</li><li>打造核心管理模块，实现服务器状态表格可视化，开发可拖拽式多窗口交互功能，模拟文件夹层级管理逻辑，通过 sessionStorage 保证窗口信息刷新不丢失；</li><li>基于 WebSocket 实现日志实时展示，采用 indexedDB 存储大体积日志并设计缓存清理机制；</li><li>开发 jar 包批量上传、日志在线编辑功能，实现后端文件流解析编辑-回传全流程，无需本地下载即可完成修改。</li></ul></li><li><p><strong>参与跨单位大屏协同开发项目</strong>：</p><ul><li>基于 Vue3+TS 负责指定模块组件化开发，保障组件的复用性与兼容性，配合团队完成大屏项目落地。</li></ul></li></ol><hr><h3 id="环亚数字经济研究院-web-前端开发-2021-09-2024-04" tabindex="-1">环亚数字经济研究院 | Web 前端开发 | 2021.09 - 2024.04 <a class="header-anchor" href="#环亚数字经济研究院-web-前端开发-2021-09-2024-04" aria-label="Permalink to &quot;环亚数字经济研究院 | Web 前端开发 | 2021.09 - 2024.04&quot;">​</a></h3><p><strong>核心方向</strong>: 政企后台管理系统 | 大屏可视化 | Mapbox 地图开发 | UniApp 小程序开发</p><ol><li><p><strong>商业云交投大脑二/三级看板（核心大屏项目）</strong>：</p><ul><li>基于 Mapbox 开发 WGS84 坐标系地图模块，封装通用地图组件，实现底图切换、点位标注、多省市地图切换、个性化气泡窗渲染，点击公司/点位可联动刷新数据图表，适配数字中心规范要求；</li></ul></li><li><p><strong>商业集团商铺管理系统</strong>：</p><ul><li>基于若依框架搭建前端架构，实现服务区平面图统一封装、高德地图多边形/点位联动渲染，开发大文件分片上传功能（基于 vue-simple-uploader）并封装为通用文件管理页面，适配多业务类型文件上传；</li></ul></li><li><p><strong>高速驿网小程序</strong>：</p><ul><li>基于 UniApp+u-view 开发定制化小程序，完成从构建、开发到发布全流程，实现服务区及司机相关定制化功能；</li></ul></li><li><p><strong>浙商互联收银系统后台管理</strong>：</p><ul><li>基于 Vue3+Vite+Pinia 开发，封装通用表格组件，通过配置快速实现表格增删改查及样式统一，提升开发效率；</li></ul></li><li><p><strong>能源管控系统</strong>：</p><ul><li>基于 Vite+Vue3+ElementPlus 开发后台管理系统，熟练运用 Vue3 核心特性完成常规业务开发。</li></ul></li></ol><hr><h3 id="北京天天智慧智电科技有限公司-web-前端开发-2020-10-2021-09" tabindex="-1">北京天天智慧智电科技有限公司 | Web 前端开发 | 2020.10 - 2021.09 <a class="header-anchor" href="#北京天天智慧智电科技有限公司-web-前端开发-2020-10-2021-09" aria-label="Permalink to &quot;北京天天智慧智电科技有限公司 | Web 前端开发 | 2020.10 - 2021.09&quot;">​</a></h3><p><strong>核心方向</strong>: 电力行业后台管理系统 | 数据驾驶舱 | Node.js 爬虫开发</p><ol><li><p><strong>售电管理用户侧平台（大渡河）</strong>：</p><ul><li>基于 AVUE 开发合同/审批/系统管理模块，攻克合同模块复杂交互难点，实现多选项卡数据统一提交、异步接口轮询及进度条展示，封装富文本、树状结构筛选、文件上传等通用小工具；</li></ul></li><li><p><strong>售电管理用户侧平台（产品化）</strong>：</p><ul><li>负责数据驾驶舱开发，通过 Proxy 代理调用 ES 服务，封装 Axios 方法实现 ES 索引数据增删改查及图表生成；</li><li>基于 Node.js+Nightmare/Puppeteer 开发爬虫，授权后采集电力公司数据并存入 MySQL，为数据中台提供数据支撑。</li></ul></li></ol><hr><h3 id="杭州德慧信息技术有限公司-web-前端开发-技术负责人-2019-10-2020-10" tabindex="-1">杭州德慧信息技术有限公司 | Web 前端开发/技术负责人 | 2019.10 - 2020.10 <a class="header-anchor" href="#杭州德慧信息技术有限公司-web-前端开发-技术负责人-2019-10-2020-10" aria-label="Permalink to &quot;杭州德慧信息技术有限公司 | Web 前端开发/技术负责人 | 2019.10 - 2020.10&quot;">​</a></h3><p><strong>核心方向</strong>: GIS 三维可视化 | 大屏项目全流程开发 | 团队技术框架搭建与版本管理</p><ol><li><p><strong>技术管理与项目统筹</strong>：</p><ul><li>作为初创公司技术负责人，牵头搭建前端 Vue 全家桶技术框架，制定团队开发规范，统筹完成团队版本管理从 Gitlab 到 SVN 的切换，带领 5 人团队落地 12 个政企级 GIS 三维可视化大屏项目，全部按时按标交付，客户满意度 100%。</li></ul></li><li><p><strong>Cesium 三维平台开发</strong>：</p><ul><li>基于 Cesium 引擎对火星科技平台进行二次开发，掌握三维模型基础原理及多格式转换与加载，实现模型单体化、视频投影等定制化功能；</li><li>落地模型加载、标注、视点、智能巡更增删改查核心功能，实现点击模型联动加载关联业务数据的交互效果。</li></ul></li><li><p><strong>IOT 数据融合与大屏落地</strong>：</p><ul><li>打通三维可视化平台与 IOT 设备数据链路，实现设备数据实时采集、统计图可视化展示，深度融合三维模型与业务数据落地大屏可视化需求；</li><li>完成杭州德慧 SE/Gsp 引擎三维可视化平台、智慧楼宇/园区/社区应急指挥平台、中国电视台大屏、大旺化工厂三维可视化平台等标杆项目，主导开发安卓端 OA 系统，适配项目全流程管理需求。</li></ul></li></ol><hr><h2 id="其他工作经历" tabindex="-1">其他工作经历 <a class="header-anchor" href="#其他工作经历" aria-label="Permalink to &quot;其他工作经历&quot;">​</a></h2><h3 id="杭州栖木科技有限公司-2018-12-2019-06" tabindex="-1">杭州栖木科技有限公司 | 2018.12 - 2019.06 <a class="header-anchor" href="#杭州栖木科技有限公司-2018-12-2019-06" aria-label="Permalink to &quot;杭州栖木科技有限公司 | 2018.12 - 2019.06&quot;">​</a></h3><ul><li>基于 Vue2 开发后台管理系统/移动端项目，封装 Axios、实现富文本/国际化，解决 UI 框架样式穿透问题，搭建前端开发环境模板。</li></ul><h3 id="浙江不动谷信息科技有限公司-2016-10-2018-12" tabindex="-1">浙江不动谷信息科技有限公司 | 2016.10 - 2018.12 <a class="header-anchor" href="#浙江不动谷信息科技有限公司-2016-10-2018-12" aria-label="Permalink to &quot;浙江不动谷信息科技有限公司 | 2016.10 - 2018.12&quot;">​</a></h3><ul><li>独立开发维护电商类微信公众号/小程序，技术栈涵盖 jQuery/Vue/微信小程序原生。</li></ul><h3 id="杭州和木电子商务有限公司-2015-10-2016-10" tabindex="-1">杭州和木电子商务有限公司 | 2015.10 - 2016.10 <a class="header-anchor" href="#杭州和木电子商务有限公司-2015-10-2016-10" aria-label="Permalink to &quot;杭州和木电子商务有限公司 | 2015.10 - 2016.10&quot;">​</a></h3><ul><li>独立开发跨境电商平台（PC/移动端/公众号），实现商品展示、购物车、订单、物流等核心电商功能。</li></ul><h3 id="浙江七巧板信息科技有限公司-2015-04-2015-10" tabindex="-1">浙江七巧板信息科技有限公司 | 2015.04 - 2015.10 <a class="header-anchor" href="#浙江七巧板信息科技有限公司-2015-04-2015-10" aria-label="Permalink to &quot;浙江七巧板信息科技有限公司 | 2015.04 - 2015.10&quot;">​</a></h3><ul><li>开发公安系统基础警务平台，适配 IE8+ 浏览器，完成切图、前端开发、浏览器兼容及接口联调。</li></ul><hr><h2 id="个人评价" tabindex="-1">个人评价 <a class="header-anchor" href="#个人评价" aria-label="Permalink to &quot;个人评价&quot;">​</a></h2><p>8年政企 GIS/数据可视化前端开发实战经验，精通 GIS 二/三维开发、Python 全流程数据处理、前端全栈技术及 Java 若依框架后端开发，可独立完成政企级 GIS/数据可视化项目从需求拆解、技术方案制定到全流程开发落地的全链路工作；熟练运用 Cursor、通义灵码等 AI 工具融入开发全流程，大幅提升项目交付效率与质量。</p><p>熟悉政务大数据开发规范与政企项目落地流程，具备优秀的需求拆解、团队统筹与项目管理能力，拥有丰富的政企项目实战与团队协作经验。未来将持续深化 GIS 与数据融合的技术能力，结合 AI 工具与全栈思维，不断提升复杂业务场景的技术落地与优化能力，为企业数字化建设提供贴合需求的技术支撑与解决方案。</p>',47)]))}const g=l(r,[["render",o]]);export{b as __pageData,g as default};
